use rsf_test_support::Window;
use std::ffi::c_void;
use windows::{
    Win32::{
        Foundation::{HWND, LPARAM, WPARAM},
        UI::WindowsAndMessaging::{SendMessageW, WS_OVERLAPPEDWINDOW},
    },
    core::PCWSTR,
};

fn require(condition: bool, message: &str) {
    if !condition {
        eprintln!("FAIL: {message}");
        std::process::exit(1);
    }
}

fn check<T, E: std::fmt::Debug>(result: Result<T, E>, message: &str) -> T {
    match result {
        Ok(value) => value,
        Err(error) => {
            eprintln!("FAIL: {message}: {error:?}");
            std::process::exit(1);
        }
    }
}

/// A hidden overlapped window of its own class; each fixture leaves foreground focus alone.
fn window(class: PCWSTR, width: i32, height: i32) -> Window {
    check(
        Window::new(class, PCWSTR::null(), WS_OVERLAPPEDWINDOW, width, height),
        "create window",
    )
}

fn send(hwnd: HWND, message: u32, wparam: usize, lparam: isize) {
    unsafe { SendMessageW(hwnd, message, Some(WPARAM(wparam)), Some(LPARAM(lparam))) };
}

type Handle = *mut c_void;
